repo.readings.py:
"""Reading records."""


class Reading:
    def __init__(self, sensor, level):
        self.sensor = sensor
        self.level = level

    def __repr__(self):
        return "Reading(%r, %r)" % (self.sensor, self.level)


ROWS = [('north', 42), ('north', 44), ('south', 8), ('south', 50), ('east', 28), ('east', 45), ('north', 10)]


def load_readings():
    """Yield the stored readings one at a time."""
    for sensor, level in ROWS:
        yield Reading(sensor, level)

repo.ranking.py:
"""Top readings by level."""


def _take_largest(readings):
    """Remove and return the reading with the largest level."""
    best = max(readings, key=lambda x: x.level)
    readings.remove(best)
    return best


def podium(readings, places=3):
    """Return the top `places` readings by level, largest first. The caller's list is left as it was."""
    top = []
    while readings and len(top) < places:
        top.append(_take_largest(readings))
    return top


def report(readings):
    """Return the podium values, the number of readings and every level."""
    return {"podium": [x.level for x in podium(readings)], "count": len(readings), "all": [x.level for x in readings]}


def describe_reading(reading):
    """Return a one-line description of a reading."""
    return "%s: %s" % (reading.sensor, reading.level)

