from readings import load_readings, ROWS
from ranking import podium, report

VALUES = [v for _, v in ROWS]


def test_count():
    assert report(list(load_readings()))["count"] == len(ROWS)


def test_all_values_kept():
    assert report(list(load_readings()))["all"] == VALUES


def test_podium_values():
    top = podium(list(load_readings()))
    assert [x.level for x in top] == sorted(VALUES, reverse=True)[:3]


def test_caller_list_unchanged():
    data = list(load_readings())
    podium(data, 2)
    assert [x.level for x in data] == VALUES


def test_one_place():
    assert [x.level for x in podium(list(load_readings()), 1)] == [max(VALUES)]
